"""Lezen: practical reading. Letters, leaflets, notices, contracts, the texts a
newcomer actually has to understand. Questions ask for a condition, an
exception, a date, or what to do; some correct answers are 'dat staat er
niet', which punishes a model that invents."""
from items_lib import mcq, extend

def q(n, bron, tekst, vraag, juist, fout):
    return mcq("lezen", n, f"{bron}:\n“{tekst}”\n\n{vraag}", juist, fout)

